using System;
using System.IO;
using System.Text;
using HostBoss;
using Kolkata.UI;
using Newtonsoft.Json;

class SlideDocumentTests {
    static int checks;
    static void Check(bool value, string name) { if (!value) throw new Exception(name); checks++; Console.WriteLine("PASS: " + name); }
    static void Reject(Action action, string name) { bool rejected = false; try { action(); } catch { rejected = true; } Check(rejected, name); }
    static int Main(string[] args) {
        try {
            var defaults = JsonConvert.DeserializeObject<ReviewSlideDeckDefinition>(File.ReadAllText(args[0]));
            var doc = new SlideDocument(args[1], defaults);
            if (args.Length > 2 && !string.IsNullOrEmpty(args[2])) {
                var savedDoc = new SlideDocument(Path.GetDirectoryName(args[2]), defaults);
                savedDoc.Load(Path.GetFileName(args[2]));
                var applied = SlideDocument.ResolveNativeContent(savedDoc.Deck, defaults, savedDoc.Options);
                Check(applied.slides[0].title == savedDoc.Deck.slides[0].title && applied.slides.Length == savedDoc.Deck.slides.Length, "reported custom save loads and composes without optional AI notes (read-only test)");
            }
            string original = defaults.slides[0].title;
            doc.Deck.slides[0].title = "Custom title";
            Check(defaults.slides[0].title == original, "editing a draft leaves templates unchanged");
            doc.Selected = 0; doc.Add(doc.Deck.slides[0]);
            Check(doc.Selected == 1 && doc.Deck.slides[0].id != doc.Deck.slides[1].id, "duplicate gets a unique ID and is selected");
            doc.Deck.slides[1].title = "Duplicate"; doc.Move(1);
            Check(doc.Selected == 2 && doc.Deck.slides[2].title == "Duplicate", "reorder moves the selected slide");
            doc.Remove(); Check(doc.Deck.slides.Length == defaults.slides.Length, "delete removes only the selected slide");
            doc.Replace(defaults.slides[0]); Check(doc.Deck.slides[doc.Selected].title == original, "replace uses a fresh template copy");
            doc.Set(defaults); doc.Deck.slides[0].title = "Saved title";
            doc.Deck.slides[0].quote = "A custom quote with unicode: café 🚀";
            doc.Deck.slides[0].narration = "Boss speech for this slide.";
            const string png = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aJ1sAAAAASUVORK5CYII=";
            doc.Deck.slides[0].imagePath = SlideDocument.PngPrefix + png;
            doc.Save("Round trip");
            var reloaded = new SlideDocument(args[1], defaults); reloaded.Load("Round trip");
            Check(reloaded.Deck.slides[0].title == "Saved title" && reloaded.Deck.slides[0].quote == doc.Deck.slides[0].quote, "save/load preserves title, quote and unicode");
            Check(reloaded.Deck.slides[0].imagePath == SlideDocument.PngPrefix + png, "save embeds PNG data instead of a machine file path");
            Check(reloaded.Deck.slides[0].narration == "Boss speech for this slide.", "boss narration survives save/load");
            reloaded.Selected = 0; reloaded.Add(reloaded.Deck.slides[0]);
            Check(reloaded.Deck.slides[1].narration == "Boss speech for this slide.", "duplicating a slide preserves its corresponding boss narration");
            var speechSlide = SlideDocument.Clone(defaults.slides[0]); speechSlide.title = "<b>Decision</b>"; speechSlide.quote = "Back to work!";
            Check(SlideDocument.TextForSpeech(speechSlide) == "Decision. Back to work!", "slide-to-speech text uses the title and quote without formatting tags");
            speechSlide.narration = ""; reloaded.Replace(speechSlide);
            Check(reloaded.Deck.slides[reloaded.Selected].narration == "", "replacing with a silent template does not retain the old speech");
            doc.Deck.slides[0].title = "Replacement"; doc.Save("Round trip");
            var backup = JsonConvert.DeserializeObject<SavedPresentation>(File.ReadAllText(doc.FilePath("Round trip") + ".bak")).deck;
            Check(backup.slides[0].title == "Saved title", "replacing a save keeps the previous version as a backup");
            doc.Deck.slides[0].title = "Third version"; doc.Save("Round trip");
            backup = JsonConvert.DeserializeObject<SavedPresentation>(File.ReadAllText(doc.FilePath("Round trip") + ".bak")).deck;
            Check(backup.slides[0].title == "Replacement", "repeated saves rotate the backup successfully");
            Check(doc.FilePath("Filename.json") == doc.FilePath("Filename"), "save accepts an optional .json extension");
            doc.Save("Boss's slides!"); Check(File.Exists(doc.FilePath("Boss's slides!")), "save accepts ordinary filename punctuation");
            Reject(() => doc.FilePath("CON"), "save rejects reserved Windows filenames");
            var optionsDoc = new SlideDocument(args[1], defaults);
            optionsDoc.Options.AnnounceApps = true; optionsDoc.Options.NativeTts = false;
            optionsDoc.Options.For(optionsDoc.Deck.slides[2].id).NativeHeard = true;
            optionsDoc.Options.For(optionsDoc.Deck.slides[0].id).Camera = "top-left";
            optionsDoc.Save("Native options.json"); optionsDoc.Load("Native options");
            Check(optionsDoc.Options.AnnounceApps && !optionsDoc.Options.NativeTts && optionsDoc.Options.For(optionsDoc.Deck.slides[2].id).NativeHeard && optionsDoc.Options.For(optionsDoc.Deck.slides[0].id).Camera == "top-left", "native toggles and per-slide camera survive save/load");
            Check(SlideDocument.CameraClass(optionsDoc.Options, optionsDoc.Deck.slides[0].id) == "boss-webcam--top-left", "camera selector resolves to the native webcam corner class");
            Check(SlideDocument.CameraClass(optionsDoc.Options, optionsDoc.Deck.slides[1].id) == null, "Auto camera position keeps the game's default layout");
            optionsDoc.Selected = 0; optionsDoc.Add(optionsDoc.Deck.slides[0]);
            Check(optionsDoc.Options.For(optionsDoc.Deck.slides[1].id).Camera == "top-left", "duplicating a slide preserves its camera position");
            File.WriteAllText(optionsDoc.FilePath("Legacy"), JsonConvert.SerializeObject(defaults)); optionsDoc.Load("Legacy");
            Check(optionsDoc.Deck.slides.Length == defaults.slides.Length && !optionsDoc.Options.AnnounceApps, "existing legacy deck files still load");
            var nativeDeck = SlideDocument.Clone(defaults);
            var notes = new ReviewSlideDefinition { id="runtime-ai-boss-notes", layout="checklist", title="Real evidence", narration="Original boss line", replayMoments=new[] {new ReviewReplayMoment {quote="Real caller quote", replayId="native-replay", introduction="Original intro", reaction="Original reaction", fallback="Original fallback"}} };
            var app = new ReviewSlideDefinition {id="runtime-app-tutorial-new", layout="unlock", title="New app", narration="Original app announcement"};
            var fired = new ReviewSlideDefinition {id="runtime-fired", layout="fired"};
            nativeDeck.slides = new[] {notes, app, fired};
            optionsDoc.Options.AnnounceApps = true;
            optionsDoc.Options.For(optionsDoc.Deck.slides[2].id).NativeHeard = true;
            optionsDoc.Options.For(optionsDoc.Deck.slides[2].id).Camera = "bottom-left";
            var expanded = SlideDocument.ResolveNativeContent(optionsDoc.Deck, nativeDeck, optionsDoc.Options);
            Check(expanded.slides[2].title == "Real evidence" && expanded.slides[2].replayMoments[0].replayId == "native-replay", "native heard mode inserts real evidence and selected replay IDs");
            Check(expanded.slides[2].narration == "Original boss line" && expanded.slides[expanded.slides.Length-1].narration == "Original app announcement", "native options retain original notes and app narration");
            var noNotes = SlideDocument.Clone(nativeDeck); noNotes.slides = new[] {app};
            var missingEvidence = SlideDocument.ResolveNativeContent(optionsDoc.Deck, noNotes, optionsDoc.Options);
            Check(missingEvidence.slides[0].title == optionsDoc.Deck.slides[0].title && missingEvidence.slides.Length == optionsDoc.Deck.slides.Length + 1, "missing optional notes retain the custom deck and app announcements");
            Check(missingEvidence.slides[2].quote == "No boss notes or recordings are available for this day." && missingEvidence.slides[2].replayMoments == null && missingEvidence.slides[2].narration == "", "missing evidence is explicit and never invents recordings or boss speech");
            Check(optionsDoc.Deck.slides[2].quote != missingEvidence.slides[2].quote, "missing-evidence placeholder does not change the saved draft");
            Check(optionsDoc.Options.For(expanded.slides[2].id).Camera == "bottom-left", "expanded heard slides inherit the placeholder's camera corner");
            var textMoment = new ReviewSlideDefinition {id="runtime-ai-boss-notes-0", layout="checklist", title="Actual text-only boss note", narration="The game's original reaction", bullets=new[] {new ReviewBulletDefinition {text="Actual featured quote", tone="neutral"}}};
            var videoMoment = SlideDocument.Clone(notes); videoMoment.id = "runtime-ai-boss-notes-1";
            var indexedDeck = SlideDocument.Clone(nativeDeck); indexedDeck.slides = new[] {textMoment, videoMoment, app, fired};
            var indexed = SlideDocument.ResolveNativeContent(optionsDoc.Deck, indexedDeck, optionsDoc.Options);
            Check(indexed.slides[2].id == textMoment.id && indexed.slides[2].bullets[0].text == "Actual featured quote", "0.1.81 indexed text-only boss notes are included without a recording");
            Check(indexed.slides[3].id == videoMoment.id && indexed.slides[3].replayMoments[0].replayId == "native-replay", "indexed notes and recordings retain native order and replay IDs");
            Check(indexed.slides[2].narration == textMoment.narration && optionsDoc.Options.For(textMoment.id).Camera == "bottom-left" && optionsDoc.Options.For(videoMoment.id).Camera == "bottom-left", "indexed notes preserve original TTS and inherit camera placement");
            optionsDoc.Options.NativeTts = false;
            var quiet = SlideDocument.ResolveNativeContent(optionsDoc.Deck, indexedDeck, optionsDoc.Options);
            Check(quiet.slides[2].narration == "" && quiet.slides[3].replayMoments[0].reaction == "" && textMoment.narration != "", "indexed notes respect the TTS toggle without mutating native evidence");
            optionsDoc.Options.NativeTts = true;
            Check(!SlideDocument.IsBossHeardSlide(null) && !SlideDocument.IsBossHeardSlide(new ReviewSlideDefinition {id="runtime-ai-boss-notesother-template"}), "boss-heard detection excludes null and unrelated similarly named slides");
            optionsDoc.Options.UseNativeSlides = true; optionsDoc.Options.NativeTts = false; optionsDoc.Options.AnnounceApps = false;
            expanded = SlideDocument.ResolveNativeContent(optionsDoc.Deck, nativeDeck, optionsDoc.Options);
            Check(expanded.slides.Length == 1 && expanded.slides[0].narration == "", "full native mode respects app/TTS toggles and excludes firing slides");
            Check(expanded.slides[0].replayMoments[0].introduction == "" && expanded.slides[0].replayMoments[0].reaction == "" && expanded.slides[0].replayMoments[0].fallback == "" && expanded.slides[0].replayMoments[0].replayId == "native-replay", "turning native TTS off silences boss clip commentary while retaining the recording");
            var rankingDoc = new SlideDocument(args[1], defaults);
            var rankingSlide = rankingDoc.Deck.slides[1];
            string customFirstPlayer = rankingSlide.table.rows[0][1];
            rankingSlide.title = "My rankings title";
            SlideDocument.SetBuiltInRankings(rankingSlide, true);
            rankingDoc.Save("Live Rankings"); rankingDoc.Load("Live Rankings");
            Check(SlideDocument.UsesBuiltInRankings(rankingDoc.Deck.slides[1]), "built-in rankings toggle survives save/load");
            var current = SlideDocument.Clone(defaults);
            current.slides[1].table.rows[0] = new[] {"1", "Current leader", "$900"};
            current.slides[1].table.tiers = new[] {"S", "B", "C"};
            current.slides[1].table.highlightRow = 1;
            var resolved = SlideDocument.ResolveRankings(rankingDoc.Deck, current);
            Check(resolved.slides[1].table.rows[0][1] == "Current leader" && resolved.slides[1].table.tiers[0] == "S" && resolved.slides[1].table.highlightRow == 1, "built-in mode copies the game's ordering, earnings, grades and highlight");
            Check(resolved.slides[1].title == "My rankings title", "built-in mode preserves custom slide titles");
            Check(rankingDoc.Deck.slides[1].table.rows[0][1] == customFirstPlayer, "resolving live rankings preserves saved custom rows");
            resolved.slides[1].table.rows[0][1] = "Edited snapshot";
            Check(current.slides[1].table.rows[0][1] == "Current leader", "resolved table does not mutate the native review");
            current.slides[1].table.rows[0][1] = "Tomorrow's leader";
            Check(SlideDocument.ResolveRankings(rankingDoc.Deck, current).slides[1].table.rows[0][1] == "Tomorrow's leader", "reapplying a saved deck uses the new day's rankings");
            rankingDoc.Selected = 1; rankingDoc.Add(rankingDoc.Deck.slides[1]);
            Check(SlideDocument.UsesBuiltInRankings(rankingDoc.Deck.slides[2]) && rankingDoc.Deck.slides[1].id != rankingDoc.Deck.slides[2].id, "duplicating a ranking slide retains its toggle with a unique ID");
            SlideDocument.SetBuiltInRankings(rankingDoc.Deck.slides[1], false);
            rankingDoc.Remove();
            Check(SlideDocument.ResolveRankings(rankingDoc.Deck, current).slides[1].table.rows[0][1] == customFirstPlayer, "turning built-in rankings off restores custom table behavior");
            SlideDocument.SetBuiltInRankings(rankingDoc.Deck.slides[1], true);
            Reject(() => SlideDocument.ResolveRankings(rankingDoc.Deck, null), "built-in mode refuses missing native rankings rather than showing placeholder data");
            Reject(() => doc.FilePath("../escape"), "save rejects path traversal");
            Reject(() => doc.FilePath("C:\\escape"), "save rejects absolute paths");
            Reject(() => doc.FilePath(""), "save rejects empty names");
            var snapshot = SlideDocument.Clone(doc.Deck); doc.Deck.slides[0].title = "Later draft edit";
            Check(snapshot.slides[0].title == "Third version", "later draft edits leave an applied deck snapshot unchanged");
            File.WriteAllText(doc.FilePath("Broken"), "{\"slides\":[]}");
            string prior = doc.Deck.slides[0].title;
            Reject(() => doc.Load("Broken"), "load rejects an empty/corrupt deck");
            Check(doc.Deck.slides[0].title == prior, "failed load preserves the current draft");
            var duplicateId = SlideDocument.Clone(defaults); duplicateId.slides[1].id = duplicateId.slides[0].id;
            Reject(() => SlideDocument.Validate(duplicateId), "validation rejects duplicate slide identifiers");
            var invalidPng = Convert.FromBase64String(png); invalidPng[16] = 127;
            Reject(() => SlideDocument.ValidatePng(invalidPng, 512, 16384), "PNG header blocks oversized decoded dimensions");
            Reject(() => SlideDocument.ValidatePng(new byte[34], 512, 16384), "PNG header rejects non-PNG files");
            var one = SlideDocument.Clone(defaults); one.slides = new[] {one.slides[0]};
            doc.Set(one); Reject(doc.Remove, "delete keeps at least one slide");
            while (doc.Deck.slides.Length < SlideDocument.MaxSlides) doc.Add(one.slides[0]);
            Reject(() => doc.Add(one.slides[0]), "add enforces the maximum slide count");
            foreach (var slide in doc.Deck.slides) slide.quote = new string('界', 1200);
            Check(SlideDocument.NetworkBytes(doc.Deck) > SlideDocument.MaxDeckBytes, "network budget measures UTF-8 bytes, not character count");
            Reject(() => SlideDocument.Validate(doc.Deck), "overlarge deck is rejected before network publication");
            doc.Save("Large offline draft"); doc.Load("Large offline draft");
            Check(doc.Deck.slides.Length == SlideDocument.MaxSlides, "oversized network drafts can still be saved and reloaded locally");
            Console.WriteLine(checks + " slide document checks passed."); return 0;
        } catch (Exception e) { Console.Error.WriteLine(e); return 1; }
    }
}
